const getFeatureIconColorClass = (): string => {
  return "text-[#ff1f1f]";
};

const renderSpeakingMockHighlight = (feature: string) => {
  const [firstWord, secondWord, thirdWord, fourthWord, ...restWords] =
    feature.split(" ");

  if (!firstWord || !secondWord || !thirdWord || !fourthWord) {
    return feature;
  }

  return (
    <>
      <strong>{firstWord}</strong>{" "}
      <strong>{secondWord}</strong>{" "}
      {thirdWord}{" "}
      <strong>{fourthWord}</strong>{" "}
      {restWords.join(" ")}
    </>
  );
};

