export default function PricingPage() {
  const { user, isLoading, isAuthenticated, logout } = useAuth();
  const router = useRouter();
  const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);
  const [isCardCopied, setIsCardCopied] = useState(false);

  const centerQuery = useQuery({
    queryKey: studentQueryKeys.center(user?.centerId || ""),
    queryFn: ({ signal }) => api.getCenter(user!.centerId!, { signal }),
    enabled: !!user?.centerId,
    staleTime: STUDENT_QUERY_TIMINGS.center.staleTime,
    gcTime: STUDENT_QUERY_TIMINGS.center.gcTime,
  });

  const profileQuery = useQuery({
    queryKey: studentQueryKeys.authProfile(),
    queryFn: ({ signal }) => api.getProfile({ signal }),
    enabled: !!user?.id,
    staleTime: STUDENT_QUERY_TIMINGS.profile.staleTime,
    gcTime: STUDENT_QUERY_TIMINGS.profile.gcTime,
    refetchOnWindowFocus: "always",
    placeholderData: (previousData) => previousData,
  });

  const premiumProfile = profileQuery.data as (typeof profileQuery.data & PremiumFlags) | undefined;
  const isPremiumUser = Boolean(
    premiumProfile?.premiumActive ?? premiumProfile?.isPremium ?? false,
  );
  const isGoldUser = Boolean(premiumProfile?.goldActive ?? false) && !isPremiumUser;

  const { lockedTest, requiredTier } = useMemo(() => {
    if (typeof window === "undefined") {
      return {
        lockedTest: "",
        requiredTier: null as "GOLD" | "PREMIUM" | null,
      };
    }

    const params = new URLSearchParams(window.location.search);
    const tierParam = params.get("requiredTier")?.trim().toUpperCase();

    return {
      lockedTest: params.get("lockedTest")?.trim() || "",
      requiredTier:
        tierParam === "GOLD" || tierParam === "PREMIUM"
          ? (tierParam as "GOLD" | "PREMIUM")
          : null,
    };
  }, []);

  const requiredPlanLabel = requiredTier === "GOLD" ? "Standard" : requiredTier === "PREMIUM" ? "Premium" : null;
  const centerLogo = centerQuery.data?.logo || null;

  useEffect(() => {
    if (!isLoading && !isAuthenticated) {
      router.push("/login");
    }
  }, [isLoading, isAuthenticated, router]);

  const handleCopyPaymentCard = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(PAYMENT_CARD_NUMBER);
      setIsCardCopied(true);
      window.setTimeout(() => setIsCardCopied(false), 1800);
    } catch (error) {
      console.error("Failed to copy card number:", error);
    }
  }, []);

  if (isLoading || !isAuthenticated) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-white">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-black" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      <header className="sticky top-0 z-40 border-b border-gray-200 bg-white/95 backdrop-blur">
        <div className="max-w-7xl mx-auto px-4 py-4 flex flex-wrap items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className="w-40 h-14 rounded-xl flex items-center justify-center">
              {centerLogo ? (
                <Image
                  src={centerLogo}
                  alt="Center Logo"
                  width={160}
                  height={56}
                  loading="eager"
                  className="max-h-14 h-auto w-auto object-contain"
                />
              ) : (
                <Image
                  src="/logo.png"
                  alt="logo"
                  width={160}
                  height={56}
                  loading="eager"
                  className="max-h-14 h-auto w-auto object-contain"
                />
              )}
            </div>
          </div>

          <nav className="order-3 w-full md:order-2 md:w-auto">
            <ul className="flex items-center justify-start gap-2 md:gap-4">
              <li>
                <Link
                  href="/dashboard"
                  className="inline-flex rounded-lg px-3 py-2 text-sm font-medium text-gray-600 transition-colors hover:bg-gray-100 hover:text-gray-900"
                >
                  Dashboard
                </Link>
              </li>
              <li>
                <Link
                  href="/feedback"
                  className="inline-flex rounded-lg px-3 py-2 text-sm font-medium text-gray-600 transition-colors hover:bg-gray-100 hover:text-gray-900"
                >
                  Offline Results
                </Link>
              </li>
              <li>
                <Link
                  href="/history"
                  className="inline-flex rounded-lg px-3 py-2 text-sm font-medium text-gray-600 transition-colors hover:bg-gray-100 hover:text-gray-900"
                >
                  Online Results
                </Link>
              </li>
              <li>
                <Link
                  href="/pricing"
                  className="inline-flex rounded-lg bg-black px-3 py-2 text-sm font-medium text-white"
                >
                  Pricing
                </Link>
              </li>
            </ul>
          </nav>

          <div className="order-2 md:order-3 flex items-center gap-4">
            <span className="text-gray-600">Welcome, {user?.firstName || user?.username}</span>
            <button
              onClick={() => setIsLogoutModalOpen(true)}
              className="px-4 py-2 rounded-lg bg-gray-100 text-gray-700 hover:bg-gray-200 transition-colors text-sm font-medium"
            >
              Sign Out
            </button>
          </div>
        </div>
      </header>

      <main className="mx-auto w-full max-w-7xl px-4 py-8">
        <section>
          {lockedTest ? (
            <p className="rounded-xl border border-gray-300 bg-white/90 px-3 py-2 text-xs text-gray-700">
              Locked test: <span className="font-semibold text-gray-900">{lockedTest}</span>
            </p>
          ) : null}

          {requiredPlanLabel ? (
            <p className="mt-3 rounded-xl border border-sky-300 bg-sky-50 px-3 py-2 text-xs text-sky-800">
              Recommended plan for this test: <span className="font-semibold">{requiredPlanLabel}</span>
            </p>
          ) : null}

          <div className={`grid items-stretch gap-6 lg:grid-cols-3 ${lockedTest || requiredPlanLabel ? "mt-10" : "mt-22"}`}>
            {PRICING_PLANS.map((plan) => {
              const isFree = plan.id === "FREE";
              const isGold = plan.id === "GOLD";
              const isPremium = plan.id === "PREMIUM";
              const isCurrentPlan =
                (isPremium && isPremiumUser) ||
                (isGold && isGoldUser) ||
                (isFree && !isGoldUser && !isPremiumUser);
              const isRecommendedByLock = requiredTier === plan.id;
              const [currencyLabel = "", billingLabel = ""] = (plan.priceSuffix || "").split(" ");
              const actionHref = isFree ? "/dashboard" : buildTariffTelegramLink(plan.name);
              const isPaid = !isFree;
              const circleBillingLabel = billingLabel || "monthly";

              return (
                <article
                  key={plan.id}
                  className={`relative flex h-full flex-col overflow-visible rounded-[26px] border border-gray-300 bg-white px-6 pb-7 pt-28 shadow-[0_10px_22px_rgba(0,0,0,0.2)] ${isRecommendedByLock ? "ring-2 ring-sky-400" : ""
                    }`}
                >
                  <div
                    className="absolute left-1/2 top-0 z-10 flex h-48 w-48 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full border-11 border-[#e8e8e8] bg-(--button-brand-color) text-white sm:h-52 sm:w-52"
                  >
                    {isPaid ? (
                      <div className="relative flex h-full w-full items-center justify-center text-center leading-none">
                        <div className="relative inline-flex items-center justify-center">
                          <span className="text-[38px] font-black tracking-tight sm:text-[38px]">{plan.price}</span>
                          {currencyLabel ? (
                            <span className="absolute -right-4 -top-4 px-1.5 py-0.5 text-base font-black uppercase leading-none sm:right-0 sm:text-[16px]">
                              {currencyLabel}
                            </span>
                          ) : null}
                        </div>

                        <p className="absolute bottom-8 left-1/2 -translate-x-1/2 text-[15px] font-semibold sm:bottom-12 sm:text-[18px]">
                          {circleBillingLabel}
                        </p>
                      </div>
                    ) : (
                      <span className="text-3xl font-black leading-none sm:text-[42px]">{plan.id}</span>
                    )}
                  </div>

                  <div className="text-center">
                    <h2 className="text-3xl font-bold uppercase leading-none text-[#0b0b0b] sm:text-4xl">
                      {plan.name}
                    </h2>

                    {!isPaid && plan.oldPrice ? (
                      <p className="mt-4 text-xl font-semibold text-gray-500 line-through decoration-2 sm:text-2xl">
                        {plan.oldPrice}
                      </p>
                    ) : null}

                    {!isPaid && plan.price ? (
                      <>
                        <div className="mt-1 flex items-end justify-center gap-2">
                          <span className="text-4xl font-black leading-none text-[#0b0b0b] sm:text-5xl">
                            {plan.price}
                          </span>
                          <div className="mb-1 text-left text-xs font-medium leading-[1.05] text-gray-700 sm:text-sm">
                            <p>{currencyLabel}</p>
                            <p>{billingLabel}</p>
                          </div>
                        </div>
                        <p className="mt-2 text-sm font-medium text-gray-700 sm:text-base">
                          {plan.dayPrice}
                        </p>
                      </>
                    ) : null}
                  </div>

                  <div className="mt-8 flex min-h-0 flex-1 flex-col">
                    <ul className="space-y-2.5">
                      {plan.features.map((feature) => (
                        <li
                          key={`${plan.id}-${feature}`}
                          className="flex items-center gap-2.5 text-base leading-[1.2] text-[#181818] sm:text-sm"
                        >
                          <span
                            className={`inline-flex h-6 w-6 shrink-0 items-center justify-center ${getFeatureIconColorClass()}`}
                          >
                            {renderFeatureIcon(feature)}
                          </span>
                          <span>
                            {feature === "Writing AI Checker" ? (
                              <>
                                Writing <strong>AI Checker</strong>
                              </>
                            ) : feature === "In-Depth Writing Analysis" ? (
                              <>
                                <strong>In-Depth</strong> Writing <strong>Analysis</strong>
                              </>
                            ) : feature.startsWith("3 Full CDI test") ? (
                              <>
                                <strong>3 Full</strong> CDI tests
                              </>
                            ) : feature.startsWith("10 Full CDI test") ? (
                              <>
                                <strong>10 Full</strong> CDI tests
                              </>
                            ) : feature.startsWith("20 Full CDI test") ? (
                              <>
                                <strong>20 Full</strong> CDI tests
                              </>
                            ) : feature.match(/^\d+\s+Single\s+(Reading|Listening|Writing)\s+tests/) ? (
                              feature.split(" ").map((word, index) => {
                                if (index === 0 || index === 2) {
                                  return <strong key={index}>{word} </strong>;
                                }
                                return <span key={index}>{word} </span>;
                              })
                            ) : feature.match(/^\d+\s+Speaking Mocks?\s+with\s+8\.0\s+-\s+8\.5\s+holders/) ? (
                              <>
                                {feature.split("8.0 - 8.5")[0]}
                                <strong>8.0 - 8.5</strong>
                                {feature.split("8.0 - 8.5")[1]}
                              </>
                            ) : feature.match(/^\d+\+?\s+Predicted\s+Speaking\s+Part\s+1,2,3\s+questions/) ? (
                              <>
                                <strong>{feature.split(" ")[0]}</strong>
                                {feature.substring(feature.split(" ")[0].length)}
                              </>
                            ) : feature.match(/^\d+\s+Full\s+AI-Powered\s+Speaking\s+Mock\s+Tests$/) ? (
                              renderSpeakingMockHighlight(feature)
                            ) : feature === "Daily AI Speaking Examiner" ? (
                              <>
                                Daily <strong>AI</strong> Speaking <strong>Examiner</strong>
                              </>
                            ) : feature.match(/^\d+\s+Monthly\s+Group\s+Sessions?\s+with\s+a\s+Native\s+Speaker/) ? (
                              <>
                                {feature.split("Native Speaker")[0]}
                                <strong>Native Speaker</strong>
                              </>
                            ) : (
                              feature
                            )}
                          </span>
                        </li>
                      ))}
                    </ul>

                    <div className="mt-auto pt-10">
                      <div className="flex justify-center">
                        {isFree ? (
                          <Link
                            href={actionHref}
                            className="inline-flex h-12 w-[220px] items-center justify-center rounded-xl bg-[#ff1616] px-6 text-lg font-black uppercase leading-none tracking-wide text-white shadow-[0_6px_12px_rgba(0,0,0,0.28)] transition-all hover:bg-[#e90f0f] sm:text-2xl"
                          >
                            {plan.ctaLabel}
                          </Link>
                        ) : (
                          <a
                            href={actionHref}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="inline-flex h-12 w-[220px] items-center justify-center rounded-xl bg-[#ff1616] px-6 text-lg font-black uppercase leading-none tracking-wide text-white shadow-[0_6px_12px_rgba(0,0,0,0.28)] transition-all hover:bg-[#e90f0f] sm:text-2xl"
                          >
                            {plan.ctaLabel}
                          </a>
                        )}
                      </div>
                    </div>

                    <div className="h-[80px] pt-4">
                      <div className="min-h-[44px]">
                        {isPremium ? (
                          <p className="rounded-xl bg-[#efcccc] px-3 py-2 text-center text-xs font-medium text-[#7f2a2a] sm:text-sm">
                            {isPremiumUser ? "Premium access is active" : "Most popular choice😊"}
                          </p>
                        ) : !isPremium && isCurrentPlan ? (
                          <p className="rounded-xl bg-emerald-100 px-3 py-2 text-center text-sm font-semibold text-emerald-800">
                            Current active plan
                          </p>
                        ) : null}
                      </div>

                      <div className="mt-1  text-center">
                        {plan.dayPrice ? (
                          <>
                            <p className="text-xl font-bold leading-none text-[#111111] sm:text-base">{plan.dayPrice}</p>
                            {/* <div className="mx-auto mt-2 h-[3px] w-36 rounded-full bg-[#ff1616]" /> */}
                            <div className="mx-auto w-28">
                              <svg width="139" height="15" viewBox="0 0 139 15" fill="none" xmlns="http://www.w3.org/2000/svg">
                                <path d="M0.21875 13.114C28.7188 6.78064 96.2188 -3.98602 138.219 3.61398" stroke="#FF0000" strokeWidth="2" />
                              </svg>
                            </div>
                          </>
                        ) : null}
                      </div>
                    </div>
                  </div>
                </article>
              );
            })}
          </div>

          <div className="mt-6 rounded-[28px] border border-[#D7D9DF] bg-[#FCFCFD] p-4 shadow-sm sm:p-6">
            <div className="flex flex-col gap-5">
              <div className="flex flex-wrap items-start justify-between gap-3">
                <div>
                  <p className="text-xs font-semibold uppercase tracking-[0.12em] text-[#C91E1E]">Payment</p>
                  <p className="mt-1 text-lg font-semibold leading-tight text-[#111827] sm:text-xl">
                    Transfer and activate your plan
                  </p>
                </div>

                <span className="inline-flex rounded-2xl bg-[#FCEDEE] px-4 py-2 text-xs font-semibold text-[#C91E1E]">
                  2 quick steps
                </span>
              </div>

              <div className="rounded-2xl border border-[#D7D9DF] bg-[#F8F9FB] p-4 sm:p-5">
                <p className="text-xs font-semibold uppercase tracking-[0.12em] text-[#C91E1E]">Card Number</p>

                <div className="mt-2 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
                  <p className="break-all text-lg font-semibold leading-tight tracking-[0.15em] text-[#111827] sm:text-2xl">
                    {PAYMENT_CARD_NUMBER}
                  </p>

                  <button
                    type="button"
                    onClick={handleCopyPaymentCard}
                    className={`inline-flex min-w-[136px] items-center justify-center gap-2 rounded-2xl border px-4 py-2.5 text-sm font-semibold transition-colors ${isCardCopied
                      ? "border-emerald-300 bg-emerald-50 text-emerald-700"
                      : "border-[#CFD4DD] bg-white text-[#1F2937] hover:bg-gray-100"
                      }`}
                  >
                    <svg className="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M8 16H7a2 2 0 01-2-2V7a2 2 0 012-2h7a2 2 0 012 2v1m-3 9h4a2 2 0 002-2v-4a2 2 0 00-2-2h-4a2 2 0 00-2 2v4a2 2 0 002 2z"
                      />
                    </svg>
                    {isCardCopied ? "Copied" : "Copy"}
                  </button>
                </div>

                <p className="mt-2 text-sm text-[#6B7280]">{PAYMENT_CARD_OWNER}</p>
              </div>

              <div className="rounded-2xl border border-[#D7D9DF] bg-[#F8F9FB] p-4 sm:p-5">
                <p className="text-sm font-semibold text-[#C91E1E]">After transfer</p>

                <ol className="mt-4 space-y-2 text-sm leading-relaxed text-[#1F2937]">
                  <li className="flex items-start gap-3">
                    <span className="mt-[2px] inline-flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-[#ECEEF2] text-[11px] font-semibold text-[#111827]">
                      1
                    </span>
                    <span>Take a screenshot of your payment receipt.</span>
                  </li>
                  <li className="flex items-start gap-3">
                    <span className="mt-[2px] inline-flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-[#ECEEF2] text-[11px] font-semibold text-[#111827]">
                      2
                    </span>
                    <span>
                      Send receipt + email/username + selected tariff to <br></br>{" "}
                      <a
                        href={PAYMENT_TELEGRAM_LINK}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="font-semibold text-[#C91E1E] underline underline-offset-2 hover:text-[#AF1A1A] text-base"
                      >
                        {PAYMENT_TELEGRAM_LABEL}
                      </a>
                    </span>
                  </li>
                </ol>

                <div className="mt-5">
                  <a
                    href={PAYMENT_TELEGRAM_LINK}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex items-center gap-2 rounded-2xl bg-linear-to-b from-[#FF2A2A] to-[#E31515] px-5 py-3 text-sm font-semibold text-white shadow-[0_8px_20px_rgba(227,21,21,0.35)] transition-transform hover:-translate-y-px"
                  >
                    Open Telegram
                    <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M22 2L11 13"
                      />
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M22 2L15 22L11 13L2 9L22 2Z"
                      />
                    </svg>
                  </a>
                </div>

                <p className="mt-4 text-xs font-medium text-[#6B7280]">Activation usually takes a few minutes.</p>
              </div>
            </div>
          </div>
        </section>
      </main>

      <ConfirmationModal
        isOpen={isLogoutModalOpen}
        onClose={() => setIsLogoutModalOpen(false)}
        onConfirm={logout}
        title="Sign Out"
        message="Are you sure you want to sign out?"
        confirmText="Sign Out"
        variant="danger"
      />
    </div>
  );
}
